# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">MODAL VERBS OF OBLIGATION AND NECESSITY (MUST / HAVE TO / NEED TO)</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">OBLIGATION &amp; NECESSITY (ZORUNLULUK)</text>\n  <text x="32" y="88" font-size="10.8" font-weight="bold" fill="#1e3a8a">• MUST + V1 (İçsel zorunluluk / güçlü tavsiye):</text>\n  <text x="40" y="106" font-size="10.3" fill="#1e3a8a">"I must get enough sleep to stay focused."</text>\n  <text x="32" y="128" font-size="10.8" font-weight="bold" fill="#1e3a8a">• HAVE TO / HAS TO + V1 (Dışsal kural / yasa):</text>\n  <text x="40" y="146" font-size="10.3" fill="#1e3a8a">"Students have to wear a helmet while cycling."</text>\n  <text x="32" y="168" font-size="10.8" font-weight="bold" fill="#1e3a8a">• NEED TO + V1 (Gereklilik / ihtiyaç):</text>\n  <text x="40" y="186" font-size="10.3" fill="#1e3a8a">"You need to drink at least two liters of water."</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">PROHIBITION vs. LACK OF NECESSITY</text>\n  <text x="372" y="88" font-size="10.8" font-weight="bold" fill="#7f1d1d">• MUSTN\'T + V1 (Yasaklama / Prohibition!):</text>\n  <text x="380" y="106" font-size="10.3" fill="#7f1d1d">Yapılması yasak veya tehlikelidir!</text>\n  <text x="380" y="122" font-size="10.3" fill="#7f1d1d">"You mustn\'t skip breakfast or take wrong pills."</text>\n  <text x="372" y="146" font-size="10.8" font-weight="bold" fill="#166534">• DON\'T HAVE TO / NEEDN\'T (Gerek yok!):</text>\n  <text x="380" y="164" font-size="10.3" fill="#14532d">Zorunluluk yoktur; ister yaparsın ister yapmazsın.</text>\n  <text x="380" y="180" font-size="10.3" fill="#14532d">"You don\'t have to join a gym to exercise."</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Kritik Fark: "Mustn\'t" yasak bildirir; "Don\'t have to / Don\'t need to / Needn\'t" ise zorunluluk olmadığını bildirir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">MANAGING STRESS &amp; MAINTAINING WELL-BEING VOCABULARY</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">STRESS MANAGEMENT STRATEGIES</text>\n  <text x="32" y="88" font-size="10.8" fill="#14532d">• cope with / deal with stress : stresle başa çıkmak</text>\n  <text x="32" y="110" font-size="10.8" fill="#14532d">• relieve / reduce anxiety : kaygıyı azaltmak / gidermek</text>\n  <text x="32" y="132" font-size="10.8" fill="#14532d">• practice mindfulness / breathing : nefes egzersizi</text>\n  <text x="32" y="154" font-size="10.8" fill="#14532d">• keep a gratitude journal : şükür/duygu günlüğü tutmak</text>\n  <text x="32" y="176" font-size="10.8" fill="#14532d">• set realistic goals &amp; prioritize : gerçekçi hedef koymak</text>\n  <text x="32" y="196" font-size="10.8" fill="#14532d">• maintain work-life balance : yaşam dengesini korumak</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">CAUSES &amp; SYMPTOMS OF BURNOUT</text>\n  <text x="372" y="88" font-size="10.8" fill="#78350f">• burnout / chronic fatigue : tükenmişlik / kronik yorgunluk</text>\n  <text x="372" y="110" font-size="10.8" fill="#78350f">• sleep deprivation / insomnia : uykusuzluk</text>\n  <text x="372" y="132" font-size="10.8" fill="#78350f">• procrastination : işleri erteleme alışkanlığı</text>\n  <text x="372" y="154" font-size="10.8" fill="#78350f">• peer pressure &amp; exam anxiety : akran baskısı / sınav kaygısı</text>\n  <text x="372" y="176" font-size="10.8" fill="#78350f">• digital overload / screen addiction : ekran bağımlılığı</text>\n  <text x="372" y="196" font-size="10.8" fill="#78350f">• emotional resilience : duygusal dayanıklılık / sağlamlık</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Physical health and mental well-being are interconnected; regular exercise releases endorphins.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">THEME 3 REVIEW: ADVICE, OBLIGATION &amp; CAUSE-EFFECT LINKERS</text>\n  <rect x="20" y="42" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="64" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">GIVING ADVICE &amp; WARNING</text>\n  <text x="32" y="88" font-size="10.5" fill="#1e3a8a">• should / shouldn\'t + V1</text>\n  <text x="32" y="108" font-size="10.5" fill="#1e3a8a">• ought to / ought not to + V1</text>\n  <text x="32" y="128" font-size="10.5" fill="#1e3a8a">• had better (not) + V1</text>\n  <text x="32" y="148" font-size="10.5" fill="#1e3a8a">• Why don\'t you + V1...?</text>\n  <text x="32" y="168" font-size="10.5" fill="#1e3a8a">• If I were you, I would + V1</text>\n  <text x="32" y="188" font-size="10.5" fill="#1e3a8a">• It\'s a good idea to + V1</text>\n  <rect x="245" y="42" width="210" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">RULES &amp; NECESSITY</text>\n  <text x="257" y="88" font-size="10.5" fill="#581c87">• must + V1 (Internal)</text>\n  <text x="257" y="108" font-size="10.5" fill="#581c87">• have to / has to + V1 (External)</text>\n  <text x="257" y="128" font-size="10.5" fill="#581c87">• need to + V1 (Necessity)</text>\n  <text x="257" y="148" font-size="10.5" fill="#581c87">• mustn\'t + V1 (Prohibition)</text>\n  <text x="257" y="168" font-size="10.5" fill="#581c87">• don\'t have to + V1 (Optional)</text>\n  <text x="257" y="188" font-size="10.5" fill="#581c87">• needn\'t + V1 (No need)</text>\n  <rect x="470" y="42" width="210" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="575" y="64" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#065f46">CONSEQUENCES &amp; LINKERS</text>\n  <text x="482" y="88" font-size="10.5" fill="#064e3b">• otherwise / or else (aksi hâlde)</text>\n  <text x="482" y="108" font-size="10.5" fill="#064e3b">• therefore / as a result (bu yüzden)</text>\n  <text x="482" y="128" font-size="10.5" fill="#064e3b">• lead to / result in (yol açmak)</text>\n  <text x="482" y="148" font-size="10.5" fill="#064e3b">• because of / due to (-den dolayı)</text>\n  <text x="482" y="168" font-size="10.5" fill="#064e3b">• If + Simple Present, will/can</text>\n  <text x="482" y="188" font-size="10.5" fill="#064e3b">• Unless (= If ... not)</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Theme 3 combines healthy lifestyle vocabulary with modals of advice, obligation and result clauses.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
